3	import java.net.URI;
4	import java.time.Instant;
5	import java.util.List;
6	
7	import org.springframework.http.HttpStatus;
8	import org.springframework.http.ProblemDetail;
9	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
10	
11	/**
12	 * Builds {@link ProblemDetail} bodies with the fields common to every escalation handler
13	 * (title = exception simple name, timestamp, empty schemaValidationErrors placeholder).
14	 */
15	final class ProblemDetails {
16	
17	    private ProblemDetails() {
18	    }
19	
20	    static ProblemDetail build(Exception ex, HttpStatus status, String detail) {
21	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
22	        problemDetail.setType(URI.create("about:blank"));
23	        problemDetail.setTitle(ex.getClass().getSimpleName());
24	        problemDetail.setDetail(detail);
25	        problemDetail.setProperty("timestamp", Instant.now());
26	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
27	        return problemDetail;
28	    }
29	}
